Example success response:
{
  "success": true,
  "result": {
    "fullName": "John Doe",
    "email": "john@example.com",
    "mobileNumber": "1234567890",
    "job": "Developer",
    "subject": "Support",
    "message": "Help needed",
    "isSubmittedSuccessfully": true
  },
  "errors": []
}
            
Example error response:
{
  "success": false,
  "result": null,
  "errors": [ { "key": "Validation", "message": "Invalid input data." } ]
}

